INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ich nur am Projektende über meine Arbeit nachdenke?', 2, '[{"text": "Nein", "correct": true, "because": "Regelmäßige Reflexion fördert Lernen"}, {"text": "Ja", "correct": false, "because": "Kontinuierliches Nachdenken effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft mir, meine Entscheidungen systematisch zu überprüfen?', 3, '[{"text": "SWOT-Analyse", "correct": true, "because": "Bewertet Stärken und Schwächen"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Zeigt Zeitpläne"}, {"text": "ER-Diagramm", "correct": false, "because": "Für Datenmodelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente machen ein Nachdenken über Prozesse effektiv?', 5, '[{"text": "Klar definierte Fragen", "correct": true, "because": "Lenkt Fokus"}, {"text": "Offenes Feedback", "correct": true, "because": "Fördert Ehrlichkeit"}, {"text": "Hohe Teilnehmerzahl", "correct": false, "because": "Kann unübersichtlich sein"}, {"text": "Spontane Diskussion", "correct": false, "because": "Fehlt Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Reflexion verbessert Teamarbeit. b) Sie ersetzt konkrete Maßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reflexion ergänzt Maßnahmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich über vergangene Projekte nachdenke?', 4, '[{"text": "Erfolge und Misserfolge", "correct": false, "because": "Kern der Analyse"}, {"text": "Teamdynamik", "correct": false, "because": "Beeinflusst Ergebnisse"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein primärer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Tagebuch für die Selbstanalyse hilfreich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Dokumentiert Gedanken klar"}, {"text": "Nein", "correct": false, "because": "Struktur fördert Erkenntnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt mich bei der Analyse von Teamprozessen?', 4, '[{"text": "Retrospektive", "correct": true, "because": "Fördert strukturierte Diskussion"}, {"text": "Code-Review", "correct": false, "because": "Nur für Software"}, {"text": "Budgetplan", "correct": false, "because": "Finanzfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Nachdenken über Arbeit nur für Manager ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle profitieren davon"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Reflexion nur für Fehleranalyse da?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Erfolge werden betrachtet"}, {"text": "Ja", "correct": false, "because": "Umfassender Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern eine gute Selbstanalyse?', 5, '[{"text": "Ehrliches Feedback", "correct": true, "because": "Zeigt blinde Flecken"}, {"text": "Strukturierte Fragen", "correct": true, "because": "Lenkt Gedanken"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Tiefe wichtiger"}, {"text": "Maximale Teilnehmer", "correct": false, "because": "Kann ablenken"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Überprüfung eines Projekts priorisieren?', 4, '[{"text": "Lernchancen erkennen", "correct": true, "because": "Fördert Verbesserung"}, {"text": "Schnelles Abschließen", "correct": false, "because": "Tiefe wichtiger"}, {"text": "Schuldzuweisungen", "correct": false, "because": "Kontraproduktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Reflexion braucht Zeit. b) Sie garantiert sofortige Lösungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Lösungen folgen später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine effektive Selbstanalyse?', 3, '[{"text": "Klar definierte Ziele", "correct": false, "because": "Fokussiert Reflexion"}, {"text": "Ruhige Umgebung", "correct": false, "because": "Fördert Konzentration"}, {"text": "Teure Software", "correct": true, "because": "Kein Muss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich ein Team nach einem Projekt analysiere?', 4, '[{"text": "Mit einer moderierten Retrospektive", "correct": true, "because": "Strukturiert Feedback"}, {"text": "Nur individuelle Berichte", "correct": false, "because": "Fehlt Teamdiskussion"}, {"text": "Ohne Agenda", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Nachdenken über Prozesse Zeitverschwendung ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Verbessert zukünftige Arbeit"}, {"text": "Ja", "correct": false, "because": "Bringt Erkenntnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik hilft, versteckte Probleme aufzudecken?', 4, '[{"text": "5-Why-Methode", "correct": true, "because": "Findet Ursachen"}, {"text": "Mindmapping", "correct": false, "because": "Sammelt Ideen"}, {"text": "Zeitmanagement", "correct": false, "because": "Fokus auf Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Reflexion die Planung?', 2, '[{"text": "Nein", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Ja", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine strukturierte Selbstanalyse?', 5, '[{"text": "Bessere Entscheidungen", "correct": true, "because": "Klarheit über Schwächen"}, {"text": "Kontinuierliches Lernen", "correct": true, "because": "Fördert Entwicklung"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Tiefe wichtiger"}, {"text": "Weniger Aufwand", "correct": false, "because": "Braucht Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Teamreflexion unwichtig?', 3, '[{"text": "Offene Kommunikation", "correct": false, "because": "Fördert Ehrlichkeit"}, {"text": "Klarer Fokus", "correct": false, "because": "Sichert Ergebnisse"}, {"text": "Raumdekoration", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich meine Arbeitsweise verbessern will?', 4, '[{"text": "Regelmäßige Selbstbewertung", "correct": true, "because": "Erkennt Muster"}, {"text": "Nur Feedback ignorieren", "correct": false, "because": "Feedback ist wertvoll"}, {"text": "Spontane Änderungen", "correct": false, "because": "Unstrukturiert"}]');
